#define NUM_STEPS 32
#define PI 3.141592
#define EPSILON 1e-3

const float SEA_HEIGHT = 0.6;
const float SEA_CHOPPY = 4.0;
const float SEA_SPEED = 0.8;
const float SEA_FREQ = 0.16;
const vec3 SEA_BASE = vec3(0.0, 0.09, 0.18);
const vec3 SEA_WATER_COLOR = vec3(0.8, 0.9, 0.6) * 0.6;
#define SEA_TIME (iTime * SEA_SPEED)
const mat2 octave_m = mat2(1.6, 1.2, -1.2, 1.6);

float hash(vec2 p) {
    float h = dot(p, vec2(127.1, 311.7));
    return fract(sin(h) * 43758.5453123);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(
        mix(hash(i + vec2(0.0, 0.0)), hash(i + vec2(1.0, 0.0)), u.x),
        mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x),
        u.y
    );
}

float diffuse(vec3 n, vec3 l, float p) {
    return pow(dot(n, l) * 0.4 + 0.6, p);
}

float sea_octave(vec2 uv, float choppy) {
    uv += noise(uv);
    vec2 wv = 1.0 - abs(sin(uv));
    vec2 swv = abs(cos(uv));
    wv = mix(wv, swv, wv);
    return pow(1.0 - pow(wv.x * wv.y, 0.65), choppy);
}

float map(vec3 p) {
    float freq = SEA_FREQ;
    float amp = SEA_HEIGHT;
    float choppy = SEA_CHOPPY;
    vec2 uv = p.xz;
    uv.x *= 0.75;

    float d, h = 0.0;
    for (int i = 0; i < 3; i++) {
        d = sea_octave((uv + SEA_TIME) * freq, choppy);
        d += sea_octave((uv - SEA_TIME) * freq, choppy);
        h += d * amp;
        uv *= octave_m;
        freq *= 1.9;
        amp *= 0.22;
        choppy = mix(choppy, 1.0, 0.2);
    }
    return p.y - h;
}

vec3 getNormal(vec3 p) {
    float eps = 0.1;
    vec3 n;
    n.y = map(p);
    n.x = map(vec3(p.x + eps, p.y, p.z)) - n.y;
    n.z = map(vec3(p.x, p.y, p.z + eps)) - n.y;
    n.y = eps;
    return normalize(n);
}

vec3 getSeaColor(vec3 p, vec3 n, vec3 lightDir, vec3 eyeDir) {
    float fresnel = clamp(1.0 - dot(n, -eyeDir), 0.0, 1.0);
    fresnel = pow(fresnel, 3.0) * 0.5;

    vec3 refracted = SEA_BASE + SEA_WATER_COLOR * diffuse(n, lightDir, 80.0);

    return refracted;
}

float trace(vec3 ori, vec3 dir) {
    float tm = 0.0;
    float tx = 1000.0;
    for (int i = 0; i < NUM_STEPS; i++) {
        float t = (tm + tx) * 0.5;
        vec3 p = ori + dir * t;
        float h = map(p);
        if (abs(h) < EPSILON) return t;
        if (h < 0.0) tx = t;
        else tm = t;
    }
    return tx;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    uv = uv * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    vec3 ori = vec3(0.0, 3.5, 5.0);
    vec3 dir = normalize(vec3(uv, -1.0));

    float t = trace(ori, dir);

    if (t < 1000.0) {
        vec3 p = ori + dir * t;
        vec3 n = getNormal(p);
        vec3 lightDir = normalize(vec3(0.0, 1.0, 0.8));
        vec3 eyeDir = -dir;

        vec3 color = getSeaColor(p, n, lightDir, eyeDir);
        fragColor = vec4(color, 1.0);
    } else {
        fragColor = vec4(0.0, 0.0, 0.0, 1.0);
    }
}
